#include <iostream>
#include <string>
#include <sstream>

int main() {
    std::string totalLines;
    std::getline(std::cin, totalLines);
    std::string data;
    std::getline(std::cin, data);

    int maxLen = 0;
    int tokenCount = 0;
    size_t currentIndex = 0;
    size_t lastIndex = 0;

    while (true) {
        size_t openParen = data.find('(', currentIndex);
        if (openParen == std::string::npos) break;
        size_t closeParen = data.find(')', openParen);
        if (closeParen == std::string::npos) break;

        std::string segment = data.substr(lastIndex, openParen - lastIndex);
        std::istringstream segmentStream(segment);
        std::string token;
        while (std::getline(segmentStream, token, '_')) {
            if (token.length() > maxLen) maxLen = token.length();
        }

        std::string inside = data.substr(openParen + 1, closeParen - openParen - 1);
        std::istringstream insideStream(inside);
        while (std::getline(insideStream, token, '_')) {
            if (!token.empty()) tokenCount++;
        }

        lastIndex = closeParen + 1;
        currentIndex = closeParen + 1;
    }

    // Process tail after last parenthesis
    std::string tail = data.substr(lastIndex);
    std::istringstream tailStream(tail);
    std::string tailToken;
    while (std::getline(tailStream, tailToken, '_')) {
        if (tailToken.length() > maxLen) maxLen = tailToken.length();
    }

    std::cout << maxLen << " " << tokenCount << std::endl;
    return 0;
}

